87	bool is_rvv(const std::string& mnemonic) {
88	  if (mnemonic.size() < 2) return false;
89	  char lo = static_cast<char>(
90	      tolower(static_cast<unsigned char>(mnemonic[0])));
91	  return lo == 'v' && std::isalpha(static_cast<unsigned char>(mnemonic[1]));
92	}
93	
94	std::vector<RvvInsn> rvv_in_range(const Disasm& disasm, uint64_t s,
95	                                  uint64_t e) {
96	  std::vector<RvvInsn> out;
97	  auto it = disasm.lower_bound(s);
98	  while (it != disasm.end() && it->first <= e) {
99	    if (is_rvv(it->second.mnemonic))
100	      out.push_back({it->first, it->second.mnemonic, it->second.operands});
101	    ++it;
102	  }
103	  return out;
104	}
105	
106	std::vector<CallInsn> calls_in_range(const Disasm& disasm, uint64_t s,
107	                                     uint64_t e) {
108	  std::vector<CallInsn> out;
109	  static const std::regex callee_re("<([^>]+)>");
110	  auto it = disasm.lower_bound(s);
111	  while (it != disasm.end() && it->first <= e) {
112	    std::string lo = it->second.mnemonic;
113	    std::transform(lo.begin(), lo.end(), lo.begin(),
114	                   [](unsigned char c) { return tolower(c); });
115	    if (kCallMnemonics.count(lo)) {
116	      std::smatch m;
117	      std::string target = "(indirect)";
118	      if (std::regex_search(it->second.operands, m, callee_re)) target = m[1];
119	      out.push_back({it->first, it->second.mnemonic, target});
120	    }
121	    ++it;
122	  }
123	  return out;
124	}
