126	std::vector<LoopEdge> filter_loops(std::vector<LoopEdge> rows, int min_iters,
127	                                   bool rvv_only, const Disasm& disasm,
128	                                   int limit) {
129	  rows.erase(std::remove_if(rows.begin(), rows.end(),
130	                            [&](const LoopEdge& r) {
131	                              return r.iters <
132	                                     static_cast<uint64_t>(min_iters);
133	                            }),
134	             rows.end());
135	  if (rvv_only) {
136	    rows.erase(std::remove_if(rows.begin(), rows.end(),
137	                              [&](const LoopEdge& r) {
138	                                return rvv_in_range(disasm, r.start, r.end)
139	                                    .empty();
140	                              }),
141	               rows.end());
142	  }
143	  std::sort(rows.begin(), rows.end(),
144	            [](const LoopEdge& a, const LoopEdge& b) {
145	              return a.iters > b.iters;
146	            });
147	  if (static_cast<int>(rows.size()) > limit)
148	    rows.resize(static_cast<size_t>(limit));
149	  return rows;
150	}
151	
152	std::vector<Loop> build_loops(const std::vector<LoopEdge>& rows, int limit) {
153	  std::vector<Loop> loops;
154	  int n = std::min(static_cast<int>(rows.size()), limit);
155	  loops.reserve(static_cast<size_t>(n));
156	  for (int i = 0; i < n; ++i)
157	    loops.push_back({"L" + std::to_string(i + 1),
158	                     rows[static_cast<size_t>(i)].start,
159	                     rows[static_cast<size_t>(i)].end,
160	                     rows[static_cast<size_t>(i)].iters,
161	                     -1,
162	                     {}});
163	
164	  // Parent: the smallest enclosing range; identical ranges never nest.
165	  for (int i = 0; i < n; ++i) {
166	    int best = -1;
167	    uint64_t best_sz = UINT64_MAX;
168	    for (int j = 0; j < n; ++j) {
169	      if (j == i) continue;
170	      if (loops[j].start == loops[i].start && loops[j].end == loops[i].end)
171	        continue;
172	      if (loops[j].start <= loops[i].start && loops[i].end <= loops[j].end) {
173	        uint64_t sz = loops[j].end - loops[j].start;
174	        if (sz < best_sz) {
175	          best = j;
176	          best_sz = sz;
177	        }
178	      }
179	    }
180	    loops[static_cast<size_t>(i)].parent = best;
181	  }
182	  for (int i = 0; i < n; ++i)
183	    if (loops[static_cast<size_t>(i)].parent >= 0)
184	      loops[static_cast<size_t>(loops[static_cast<size_t>(i)].parent)]
185	          .children.push_back(i);
186	
187	  return loops;
188	}
189	
190	uint64_t measure_ret_pc(const Disasm& disasm, uint64_t fn_entry,
191	                        uint64_t fn_end) {
192	  uint64_t ret_pc = fn_end - 4;  // safe default (standard ret is 4 bytes)
193	  auto it = disasm.lower_bound(fn_end);
194	  if (it != disasm.begin()) {
195	    --it;
196	    if (it->first >= fn_entry) ret_pc = it->first;
197	  }
198	  return ret_pc;
199	}
