432	std::vector<std::string> profile_qemu_argv(const ProfileQemuArgs& a) {
433	  std::vector<std::string> argv = {
434	      a.qemu_bin,
435	      "-plugin",
436	      a.plugin_so + ",limit=" + std::to_string(a.limit) +
437	          ",min_iters=" + std::to_string(a.min_iters),
438	      "-d", "plugin", "-D", a.log_path,
439	      "-M", "andes_ae350",
440	      "-cpu", a.cpu,
441	      "-nographic", "-semihosting",
442	      "-bios", a.elf,
443	  };
444	  if (!a.mem_size.empty()) {
445	    argv.push_back("-m");
446	    argv.push_back(a.mem_size);
447	  }
448	  if (!a.readconfig.empty()) {
449	    argv.push_back("-readconfig");
450	    argv.push_back(a.readconfig);
451	  }
452	  argv.insert(argv.end(), a.passthrough.begin(), a.passthrough.end());
453	  return argv;
454	}
