1	// Profile core -- the pure logic behind `andesim profile` (hot inner-loop
2	// detection via the hotIterationLoop TCG plugin).
3	//
4	// Everything here is data-in/data-out: plugin-log text -> loop edges,
5	// objdump text -> a disassembly map, filters/nesting on plain structs, and
6	// renderers that RETURN the report as a string. All process IO (QEMU spawn,
7	// objdump/addr2line, ELF symbolization) stays in cmd_profile.cpp, which
8	// precomputes per-loop symbol/source strings into LoopSyms so the renderers
9	// need no filesystem access -- that is what makes them unit-testable.
10	#ifndef ANDESIM_PROFILE_HPP
11	#define ANDESIM_PROFILE_HPP
12	
13	#include <cstdint>
14	#include <map>
15	#include <string>
16	#include <utility>
17	#include <vector>
18	
19	namespace andes_sim {
20	
21	// One backward edge observed by the plugin: header pc, tail pc, iterations.
22	struct LoopEdge {
23	  uint64_t start = 0;
24	  uint64_t end = 0;
25	  uint64_t iters = 0;
26	};
27	
28	// One disassembled instruction (objdump -d --no-show-raw-insn).
29	struct InsnInfo {
30	  std::string mnemonic;
31	  std::string operands;
32	};
33	using Disasm = std::map<uint64_t, InsnInfo>;
34	
35	struct RvvInsn {
36	  uint64_t pc;
37	  std::string mn, ops;
38	};
39	struct CallInsn {
40	  uint64_t pc;
41	  std::string mn, target;
42	};
43	
44	// A loop after nesting: parent/children reference loops in the SAME vector by
45	// index (-1 = top-level), so the vector stays copyable.
46	struct Loop {
47	  std::string id;  // "L1".."Ln", hottest first
48	  uint64_t start = 0, end = 0, iters = 0;
49	  int parent = -1;
50	  std::vector<int> children;
51	};
52	
53	// Per-loop symbol/source strings, precomputed by the caller (ELF + addr2line
54	// IO) so the renderers stay pure. Empty string = unknown.
55	struct LoopSyms {
56	  std::string sym_start;     // "name+0xoff" or raw "0x<pc>" at loop.start
57	  std::string sym_end;       // same at loop.end
58	  std::string fn_name;       // bare function name at loop.start
59	  uint64_t fn_entry = 0;     // fn_range(loop.start); 0,0 = unknown
60	  uint64_t fn_end = 0;
61	  std::string src_start;     // full addr2line "path:line" at loop.start
62	  std::string src_end;       // same at loop.end
63	  std::string code_snippet;  // trimmed source text at src_start
64	};
65	
66	// The plugin's `-d plugin -D <file>` log -> edges. Header/garbage lines are
67	// skipped; rows are `0x<start>, 0x<end>, <iters>`.
68	std::vector<LoopEdge> parse_plugin_log(const std::string& text);
69	
70	// `objdump -d --no-show-raw-insn` text -> pc-keyed instruction map. Works for
71	// both GNU and LLVM objdump; label lines carry no colon-after-hex and drop out.
72	Disasm parse_disasm(const std::string& raw);
73	
74	// RVV mnemonic heuristic: 'v' followed by a letter (vadd.vv, vsetvli, ...).
75	bool is_rvv(const std::string& mnemonic);
76	
77	// The RVV / call instructions inside [s, e] (inclusive).
78	std::vector<RvvInsn> rvv_in_range(const Disasm& disasm, uint64_t s, uint64_t e);
79	std::vector<CallInsn> calls_in_range(const Disasm& disasm, uint64_t s,
80	                                     uint64_t e);
81	
82	// Drop rows below min_iters (and, when rvv_only, rows whose body holds no RVV
83	// instruction), sort by iterations desc, truncate to limit.
84	std::vector<LoopEdge> filter_loops(std::vector<LoopEdge> rows, int min_iters,
85	                                   bool rvv_only, const Disasm& disasm,
86	                                   int limit);
87	
88	// Assign ids L1..Ln (row order; rows arrive hottest-first) and compute
89	// nesting: parent = the smallest strictly-enclosing range (identical ranges
90	// excluded), children = the inverse.
91	std::vector<Loop> build_loops(const std::vector<LoopEdge>& rows, int limit);
92	
93	// The `measure:` window's end: the last disassembled pc inside
94	// [fn_entry, fn_end), falling back to fn_end - 4 when the disasm has none.
95	uint64_t measure_ret_pc(const Disasm& disasm, uint64_t fn_entry,
96	                        uint64_t fn_end);
97	
98	// "path:line[ extra]" -> "basename:line[ extra]".
99	std::string src_basename(const std::string& s);
100	
101	// "path:line[:col]" -> {path, line}; {"", 0} for empty / "??" strings.
102	std::pair<std::string, int> parse_file_line(const std::string& s);
103	
104	// The LLM-ready Markdown report. `loops` must be non-empty; `syms` is
105	// parallel to `loops`; `target_name` is the ELF basename shown as target:.
106	std::string render_llm(const std::vector<Loop>& loops,
107	                       const std::vector<LoopSyms>& syms, uint64_t total_iters,
108	                       const std::string& target_name, const Disasm& disasm,
109	                       int min_iters, bool rvv_filter);
110	
111	// The plain aligned table. `syms` is parallel to `rows`; the source column
112	// appears only when some row has source info.
113	std::string render_table(const std::vector<LoopEdge>& rows,
114	                         const std::vector<LoopSyms>& syms, int min_iters,
115	                         bool rvv_filter);
116	
117	// Everything the QEMU launch needs, resolved by the caller (engine registry,
118	// --print-qemu-config probe, CLI flags). Empty mem_size/readconfig omit the
119	// corresponding args.
120	struct ProfileQemuArgs {
121	  std::string qemu_bin;
122	  std::string plugin_so;
123	  std::string log_path;  // -d plugin -D <log_path>
124	  int limit = 50;
125	  int min_iters = 1;
126	  std::string cpu;  // full -cpu value, e.g. "andes-ax45mpv,vlen=512"
127	  std::string mem_size;
128	  std::string readconfig;
129	  std::string elf;
130	  std::vector<std::string> passthrough;  // extra QEMU args, verbatim
131	};
132	
133	// The full qemu-system argv for one profile run.
134	std::vector<std::string> profile_qemu_argv(const ProfileQemuArgs& a);
135	
136	}  // namespace andes_sim
137	
138	#endif  // ANDESIM_PROFILE_HPP
