55	// Does `cmd` resolve to an executable (absolute/relative path, or via PATH)?
56	bool cmd_exists(const std::string& cmd) {
57	  if (cmd.find('/') != std::string::npos)
58	    return ::access(cmd.c_str(), X_OK) == 0;
59	  const char* path_env = std::getenv("PATH");
60	  if (!path_env) return false;
61	  std::istringstream ss(path_env);
62	  std::string dir;
63	  while (std::getline(ss, dir, ':'))
64	    if (!dir.empty() && ::access((dir + "/" + cmd).c_str(), X_OK) == 0)
65	      return true;
66	  return false;
67	}
