91	// Write lines to argv's stdin; capture its stdout. Used for addr2line, which
92	// takes one hex address per input line.
93	std::string capture_with_stdin(const std::vector<std::string>& argv,
94	                               const std::string& input) {
95	  if (argv.empty()) return "";
96	  int in_fds[2], out_fds[2];
97	  if (pipe(in_fds) != 0) return "";
98	  if (pipe(out_fds) != 0) {
99	    close(in_fds[0]);
100	    close(in_fds[1]);
101	    return "";
102	  }
103	  pid_t pid = fork();
104	  if (pid < 0) {
105	    close(in_fds[0]); close(in_fds[1]);
106	    close(out_fds[0]); close(out_fds[1]);
107	    return "";
108	  }
109	  if (pid == 0) {
110	    close(in_fds[1]);
111	    close(out_fds[0]);
112	    dup2(in_fds[0], STDIN_FILENO);
113	    dup2(out_fds[1], STDOUT_FILENO);
114	    if (FILE* devnull = std::fopen("/dev/null", "w"))
115	      dup2(fileno(devnull), STDERR_FILENO);
116	    close(in_fds[0]);
117	    close(out_fds[1]);
118	    std::vector<char*> cargv;
119	    cargv.reserve(argv.size() + 1);
120	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
121	    cargv.push_back(nullptr);
122	    execvp(cargv[0], cargv.data());
123	    _exit(127);
124	  }
125	  close(in_fds[0]);
126	  close(out_fds[1]);
127	  const char* p = input.data();
128	  size_t rem = input.size();
129	  while (rem > 0) {
130	    ssize_t w = write(in_fds[1], p, rem);
131	    if (w < 0) break;
132	    p += w;
133	    rem -= static_cast<size_t>(w);
134	  }
135	  close(in_fds[1]);
136	  std::string out;
137	  char buf[4096];
138	  ssize_t n;
139	  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
140	    out.append(buf, static_cast<size_t>(n));
141	  close(out_fds[0]);
142	  int status = 0;
143	  waitpid(pid, &status, 0);
144	  return out;
145	}
