175	// The trimmed text of `path`'s line `lineno` ("" when unreadable).
176	std::string read_source_line(const std::string& path, int lineno) {
177	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
178	  std::ifstream f(path);
179	  std::string line;
180	  for (int i = 1; std::getline(f, line); ++i) {
181	    if (i != lineno) continue;
182	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
183	                             line.back() == ' ' || line.back() == '\t'))
184	      line.pop_back();
185	    auto s = line.find_first_not_of(" \t");
186	    return (s != std::string::npos) ? line.substr(s) : line;
187	  }
188	  return "";
189	}
