259	int cmd_profile(const Cli& cli) {
260	  auto fail = [](const std::string& msg) {
261	    std::fprintf(stderr, "andesim profile: %s\n", msg.c_str());
262	    return 2;
263	  };
264	
265	  // profile is not `run`: reject run-only flags loudly instead of silently
266	  // ignoring them (a silently dropped --trigger would look like a hung ROI).
267	  {
268	    const struct {
269	      bool set;
270	      const char* flag;
271	    } runonly[] = {
272	        {!cli.model.empty(), "--mode"},
273	        {!cli.trigger.empty(), "--trigger"},
274	        {!cli.pc_start.empty(), "--pc-start"},
275	        {!cli.pc_end.empty(), "--pc-end"},
276	        {cli.verify, "--verify"},
277	        {!cli.kanata.empty(), "--kanata"},
278	        {cli.gdb, "--gdb"},
279	        {!cli.gdb_port.empty(), "--gdb-port"},
280	        {cli.print_memmap, "--print-memmap"},
281	    };
282	    for (const auto& r : runonly)
283	      if (r.set)
284	        return fail(std::string(r.flag) +
285	                    " is not a profile option (profile runs the whole "
286	                    "program under QEMU; see 'andesim profile --help')");
287	  }
288	
289	  if (cli.positional.empty())
290	    return fail("missing ELF (the workload to profile)");
291	  if (cli.positional.size() > 1)
292	    return fail("unexpected argument '" + cli.positional[1] +
293	                "' (extra QEMU args go after --)");
294	
295	  int limit = 0, min_iters = 0;
296	  if (!parse_knob(cli.limit, 50, limit))
297	    return fail("--limit must be a positive integer, got '" + cli.limit + "'");
298	  if (!parse_knob(cli.min_iters, 1, min_iters))
299	    return fail("--min-iters must be a positive integer, got '" +
300	                cli.min_iters + "'");
301	
302	  // Absolute, existing ELF (QEMU's -bios resolves relative paths against its
303	  // data dir, not the CWD) -- the same up-front check run's abs_elf does.
304	  std::error_code ec;
305	  const fs::path abs = fs::absolute(cli.positional[0], ec);
306	  if (ec || !fs::is_regular_file(abs))
307	    return fail("ELF not found: " + cli.positional[0]);
308	  const std::string elf = abs.string();
309	
310	  // The engine pick: exactly hybrid's -- --engine or the sole cycle-accurate
311	  // engine, with the same errors (naming the discovered candidates).
312	  Discovery disc = discover_engines();
313	  std::string err;
314	  const EngineDescriptor* acc =
315	      resolve_accurate_engine(disc.engines, cli.engine, err);
316	  if (!acc) {
317	    std::fprintf(stderr, "andesim profile: %s\n", err.c_str());
318	    for (const std::string& w : disc.warnings)
319	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
320	    return 2;
321	  }
322	  if (std::string e = elf_engine_arch_error(elf, *acc); !e.empty())
323	    return fail(e);
324	
325	  // QEMU follows the engine's width (the arch guard above already pinned the
326	  // ELF to it; an unreadable ELF falls back to the ELF's own class, then 64).
327	  const int elf_w = elf_xlen(elf);
328	  const int xlen = acc->xlen ? static_cast<int>(acc->xlen)
329	                             : (elf_w ? elf_w : 64);
330	  const EngineDescriptor qemu = builtin_qemu_arch(xlen);
331	  const std::string plugin = profile_plugin_path().string();
332	
333	  Workdir wd;
334	  if (wd.path.empty()) return fail(wd.error);
335	
336	  // engine -> QEMU cfg, the same probe + staging the hybrid fast leg uses.
337	  // "" cfg = tolerant fallback (family-default -cpu), but SAY so: matching
338	  // the engine's ISA is the whole point of profiling through an engine.
339	  const RunResult probe =
340	      run_process({acc->bin_path, "--print-qemu-config"}, 5000);
341	  const std::string cfg = stage_qemu_cfg(wd.path, probe);
342	  std::string cpu_model = cfg.empty() ? std::string() : qemu_cpu_from_cfg(probe.out);
343	  if (cpu_model.empty()) cpu_model = "andes-ax45mpv";
344	  if (cfg.empty())
345	    log_line(kLogWarn,
346	             "[andesim] profile: engine %s gave no --print-qemu-config; "
347	             "falling back to -cpu %s (the profiled ISA may not match the "
348	             "engine)",
349	             acc->id.c_str(), cpu_model.c_str());
350	
351	  ProfileQemuArgs qa;
352	  qa.qemu_bin = qemu.bin_path;
353	  qa.plugin_so = plugin;
354	  qa.log_path = wd.path + "/plugin.log";
355	  qa.limit = limit;
356	  qa.min_iters = min_iters;
357	  qa.cpu = cpu_model + ",vlen=" + std::to_string(synced_vlen(acc->vlen));
358	  qa.mem_size = cli.mem_size;  // forwarded as plain -m; QEMU validates it
359	  qa.readconfig = cfg;
360	  qa.elf = elf;
361	  qa.passthrough = cli.passthrough;
362	  const std::vector<std::string> argv = profile_qemu_argv(qa);
363	
364	  if (cli.dry_run)
365	    return print_dry_run({argv}, {"profile [" + acc->id + "]"});
366	
367	  log_line(kLogDebug, "[andesim] profile engine=%s cpu=%s fixture=%s",
368	           acc->id.c_str(), qa.cpu.c_str(), abs.stem().string().c_str());
369	
370	  // Spawn-time checks, AFTER --dry-run so the preview needs no built QEMU.
371	  if (!fs::is_regular_file(qemu.bin_path) ||
372	      ::access(qemu.bin_path.c_str(), X_OK) != 0)
373	    return fail("qemu not found/executable: " + qemu.bin_path +
374	                " (set QEMU_BIN_DIR in config.env, or source ./setup.sh)");
375	  if (!fs::is_regular_file(plugin))
376	    return fail("plugin not built: " + plugin + " (make -C qemu_plugin)");
377	
378	  log_line(kLogTrace, "[andesim] exec profile [%s]: %s", acc->id.c_str(),
379	           render_argv(argv).c_str());
380	  const int rc = exec_passthrough(argv);
381	  if (rc == -1) return fail("failed to spawn " + qemu.bin_path);
382	  if (rc != 0)
383	    log_line(kLogWarn,
384	             "[andesim] profile: qemu exited rc=%d; the report covers what "
385	             "ran",
386	             rc);
387	
388	  std::string log_text;
389	  {
390	    std::ifstream f(qa.log_path);
391	    std::stringstream ss;
392	    ss << f.rdbuf();
393	    log_text = ss.str();
394	  }
395	
396	  if (cli.raw) {
397	    std::fputs(log_text.c_str(), stdout);
398	    return 0;
399	  }
400	
401	  auto all_rows = parse_plugin_log(log_text);
402	  if (all_rows.empty()) {
403	    std::fprintf(stderr, "andesim profile: no backward edges observed\n");
404	    return 0;
405	  }
406	  uint64_t total_iters = 0;
407	  for (const auto& r : all_rows) total_iters += r.iters;
408	
409	  // Disassembly (the RVV filter + the report's rvv/calls sections need it).
410	  const std::string objdump = resolve_objdump(cli.objdump);
411	  Disasm disasm;
412	  if (!objdump.empty() && (cli.optimize_rvv || cli.llm))
413	    disasm = parse_disasm(
414	        run_process({objdump, "-d", "--no-show-raw-insn", elf}, 60000).out);
415	  if (objdump.empty() && cli.optimize_rvv)
416	    log_line(kLogWarn,
417	             "[andesim] profile: no objdump found; the RVV filter drops "
418	             "every loop -- install a riscv objdump or pass "
419	             "--no-optimize-rvv");
420	
421	  auto rows = filter_loops(all_rows, min_iters, cli.optimize_rvv, disasm,
422	                           limit);
423	  if (rows.empty()) {
424	    std::fprintf(stderr, "andesim profile: no loops with iters >= %d%s\n",
425	                 min_iters,
426	                 cli.optimize_rvv ? " containing RVV instructions" : "");
427	    return 0;
428	  }
429	
430	  // Source resolution (addr2line), unless --no-source.
431	  std::map<uint64_t, std::string> src_map;
432	  if (!cli.no_source) {
433	    const std::string a2l = !cli.addr2line.empty()
434	                                ? cli.addr2line
435	                                : find_first({"llvm-addr2line", "addr2line",
436	                                              "riscv64-unknown-elf-addr2line",
437	                                              "riscv32-unknown-elf-addr2line",
438	                                              "riscv64-linux-gnu-addr2line"});
439	    std::vector<uint64_t> pcs;
440	    for (const auto& r : rows) {
441	      pcs.push_back(r.start);
442	      pcs.push_back(r.end);
443	    }
444	    std::sort(pcs.begin(), pcs.end());
445	    pcs.erase(std::unique(pcs.begin(), pcs.end()), pcs.end());
446	    src_map = resolve_sources(a2l, elf, pcs);
447	  }
448	
449	  std::string report;
450	  if (cli.llm) {
451	    const auto loops = build_loops(rows, limit);
452	    std::vector<LoopSyms> syms;
453	    syms.reserve(loops.size());
454	    for (const auto& l : loops)
455	      syms.push_back(make_syms(elf, l.start, l.end, src_map));
456	    report = render_llm(loops, syms, total_iters, abs.filename().string(),
457	                        disasm, min_iters, cli.optimize_rvv);
458	  } else {
459	    std::vector<LoopSyms> syms;
